// RemoteOK /api returns [legal-notice, job, job, ...].
// n8n may deliver that as many items or as one item wrapping the array.
const stripHtml = (s) => String(s ?? '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;/g, "'")
  .replace(/&#\d+;/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

let raw = $input.all().map(i => i.json);
if (raw.length === 1) {
  const only = raw[0];
  if (Array.isArray(only)) raw = only;
  else if (only && Array.isArray(only.data)) raw = only.data;
}

const out = [];
for (const j of raw) {
  if (!j || typeof j !== 'object' || !j.position || !j.url) continue; // drops legal-notice element + junk
  let url = String(j.url).trim();
  if (url.startsWith('/')) url = 'https://remoteok.com' + url;
  out.push({ json: {
    title: String(j.position).trim(),
    company: String(j.company || '').trim(),
    description: stripHtml(j.description).slice(0, 1500),
    url,
    source: 'remoteok',
    posted_at: String(j.date || '')
  } });
}
console.log('RemoteOK normalized: ' + out.length + ' jobs');
return out;

// Strong = the role is about our stack. One hit anywhere in title+description qualifies.
const STRONG = ['llm', 'gpt', 'claude', 'rag', 'langchain', 'langgraph', 'n8n', 'make.com', 'zapier',
                'chatbot', 'mcp', 'agentic', 'ai agent', 'ai automation', 'prompt engineer', 'openai', 'anthropic'];
// Weak = too common to trust in a body ("we use AI", "python a plus"). Title only.
const WEAK = ['ai', 'automation', 'python', 'machine learning', 'ml', 'agent', 'prompt'];

// ---- TITLE-ONLY exclusions (2026-07-31) ----------------------------------------------
// Seniority is decided from the TITLE, never the description: matching these against the
// full body dropped any posting that merely MENTIONED a senior role in passing.
// Filtering here instead of at the LLM is a pure cost win, measured over 250 archived jobs:
// 68 of them (27% of all Groq spend) had a senior title, ALL 68 were independently judged
// senior_only by the LLM, and NONE were ever delivered. Zero false positives in 250 samples.
// The LLM still catches the other ~92 senior roles whose titles don't say so.
const EXCLUDE_TITLE_RX = [
  /\b10\+ years\b/i,
  /\b8\+ years\b/i,
  /\bsenior\b/i,
  /\bsr\.?\s/i,
  /\bstaff\b/i,
  /\bprincipal\b/i,
  // "Lead Engineer" is seniority; "Lead Generation" is a marketing function and can be a
  // genuinely relevant automation role, so it must NOT be filtered out here.
  /\blead\b(?!\s+gen)/i,
  /\bdirector\b/i,
  /\bhead of\b/i,
  /\bvp\b/i,
  /\bvice president\b/i,
];

// ---- FULL-TEXT exclusions -------------------------------------------------------------
// Job-SEEKER phrases describe the whole post, so full-text matching is correct for these.
const EXCLUDE_TEXT = ['available for hire', 'hire me', 'looking for work', 'looking for a job', 'open to work', 'seeking work', 'seeking a job', 'offering my services'];
// 2026-09-14: forum convention - a TITLE starting with "[For Hire]" (or "Available:") is a person
// advertising their own services, not a job. 8 of the 12 jobs scored on 09-14 were these; the
// LLM gave all 8 a score of 5 / category other, i.e. two-thirds of that day's Groq spend was
// wasted on them. "[Hiring]" titles are real jobs and are NOT matched.
const EXCLUDE_SEEKER_TITLE_RX = [
  /^\s*\[\s*for\s+hire\s*\]/i,
  /^\s*available\s*:/i,
];

// DROPPED 2026-07-31, both left to the LLM which has context a keyword list cannot:
//  - 'us citizens only'    contradicts the 07-18 decision that region locks are red flags
//                          for the human to judge, not hard filters.
//  - 'security clearance'  matched "no security clearance required" - a textbook own-goal.

const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const rx = (list) => list.map(k => new RegExp('\\b' + esc(k) + '\\b', 'i'));
const strongRe = rx(STRONG);
const weakRe = rx(WEAK);
const excTextRe = rx(EXCLUDE_TEXT);

const items = $input.all();
const out = [];
const titleDropsBySource = {};
let droppedSeeker = 0;
let droppedWeak = 0;
for (const item of items) {
  const j = item.json || {};
  if (!j.title || !j.url) continue;
  const title = String(j.title);
  const text = (j.title + ' ' + (j.description || '')).toLowerCase();
  const titleLc = title.toLowerCase();
  if (!strongRe.some(r => r.test(text)) && !weakRe.some(r => r.test(titleLc))) { droppedWeak++; continue; }
  if (EXCLUDE_TITLE_RX.some(r => r.test(title))) {
    const s = String(j.source || 'unknown');
    titleDropsBySource[s] = (titleDropsBySource[s] || 0) + 1;
    continue;
  }
  if (excTextRe.some(r => r.test(text)) || EXCLUDE_SEEKER_TITLE_RX.some(r => r.test(title))) { droppedSeeker++; continue; }
  out.push(item);
}
const titleDrops = Object.keys(titleDropsBySource).reduce((a, k) => a + titleDropsBySource[k], 0);
console.log('Keyword filter kept ' + out.length + ' of ' + items.length + ' post-dedup items');
// Per-source breakdown so the seniority filter can be told apart from the 2a-1 loosening -
// specifically, how many HN comments it removed before they could be scored.
console.log('  dropped by seniority TITLE: ' + titleDrops + ' ' + JSON.stringify(titleDropsBySource));
console.log('  dropped as job-seeker posts: ' + droppedSeeker);
console.log('  dropped for no strong keyword (and no weak keyword in title): ' + droppedWeak);
return out;

const jobs = $input.all().map(i => i.json).filter(j => j && j.title && j.url);
const out = [];
for (let i = 0; i < jobs.length; i += 5) {
  out.push({ json: { batch: JSON.stringify(jobs.slice(i, i + 5)) } });
}
// Keep the chain alive on zero-job days so the 'nothing new' digest still sends
if (out.length === 0) out.push({ json: { batch: '[]' } });
console.log('Batches: ' + out.length);
return out;

const batches = $input.all();
let okBatches = 0;
const parsed = [];
for (const item of batches) {
  try {
    const j = item.json || {};
    if (j.error) { console.log('Groq batch errored: ' + String(j.error.message || j.error).slice(0, 200)); continue; }
    const content = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
    if (!content) { console.log('Groq response had no content'); continue; }
    const txt = String(content).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
    let arr;
    try { arr = JSON.parse(txt); }
    catch (e1) {
      // salvage a truncated array: keep up to the last complete object, close the bracket
      const cut = txt.slice(0, txt.lastIndexOf('}') + 1);
      arr = JSON.parse(cut + ']');
      console.log('Salvaged truncated batch JSON (' + e1.message + ')');
    }
    if (!Array.isArray(arr)) { console.log('Groq content was not a JSON array'); continue; }
    for (const r of arr) { if (r && typeof r === 'object' && r.url) parsed.push(r); }
    okBatches++;
  } catch (e) {
    console.log('Batch parse failed (skipping batch): ' + e.message);
  }
}

// Rebuild the url -> original job lookup. Emit ALL scored jobs; the gate lives in Score Gate
// so the archive branch keeps every scored job.
const jobMap = {};
let jobsIn = 0;
for (const b of $('Make Batches').all()) {
  try {
    const arr = JSON.parse(b.json.batch);
    jobsIn += arr.length;
    for (const j of arr) jobMap[j.url] = j;
  } catch (e) {}
}

// The LLM echoes the url back and it is the ONLY join key. A mangled echo (seen once while
// trialling gpt-oss: "httpshttps://...") used to fall through as `jobMap[r.url] || {}`, which
// silently produced a row with no title/company/source and archived it. Repair the one known
// corruption, then DROP anything still unmatched rather than archiving junk.
const resolveUrl = (u) => {
  const s = String(u || '').trim();
  if (jobMap[s]) return s;
  const fixed = s.replace(/^(https?)(https?:\/\/)/i, '$2');
  return jobMap[fixed] ? fixed : null;
};

const all = [];
let unmatched = 0;
for (const r of parsed) {
  const key = resolveUrl(r.url);
  if (!key) { unmatched++; console.log('Dropped - LLM returned an unknown url: ' + String(r.url).slice(0, 90)); continue; }
  all.push({ json: Object.assign({}, jobMap[key], r, { url: key, score: Number(r.score) || 0 }) });
}

console.log('Parsed ' + all.length + ' of ' + jobsIn + ' jobs sent; batches OK ' + okBatches + '/' + batches.length + '; url-unmatched ' + unmatched);
if (all.length === 0) return [{ json: { _empty: true, score: -1 } }];
return all;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const TZ = 'Asia/Bangkok';

const parseDate = (p) => {
  const s = String(p || '').trim();
  if (!s) return null;
  let d = DateTime.fromISO(s, { zone: 'utc' });
  if (!d.isValid) d = DateTime.fromRFC2822(s, { zone: 'utc' });
  if (!d.isValid) d = DateTime.fromSQL(s, { zone: 'utc' });
  if (!d.isValid) { const t = Date.parse(s); if (!isNaN(t)) d = DateTime.fromMillis(t, { zone: 'utc' }); }
  return d && d.isValid ? d : null;
};

// Compare CALENDAR days in the local zone. The old version floored a fractional UTC diff,
// so a job posted at 20:00 yesterday showed as "today" in the 09:30 digest.
const postedInfo = (p) => {
  const d = parseDate(p);
  if (!d) return null;
  const now = DateTime.now().setZone(TZ);
  const local = d.setZone(TZ);
  const days = Math.round(now.startOf('day').diff(local.startOf('day'), 'days').days);
  if (days < 0 || days > 3650) return null;
  const when = local.toFormat(local.year === now.year ? 'd LLL' : 'd LLL yyyy');
  const rel = days === 0 ? 'today' : (days === 1 ? 'yesterday' : days + 'd ago');
  return { label: when + ', ' + rel, days };
};

// 2026-09-14: ONE Telegram message per job (was: ~8 jobs packed into 1-2 messages) so each
// card can carry its own Apply / Save / Skip inline keyboard. Every output item has
// `archive_id`: '' for the header / nothing-new message (sent without buttons by the
// existing Telegram node), the job_archive row id for a job card (sent by Telegram: Job Card).
const items = $input.all().map(i => i.json).filter(j => j && j.url && !j._empty && j.score !== undefined);
if (items.length === 0) {
  return [{ json: { text: '🤖 Job digest: nothing new above threshold today.', archive_id: '' } }];
}

// Sectioning. Gigs = fixed-price / hourly freelance posts and AI-training platforms.
const isGig = (j) => j.category === 'ai_training_platform'
  || /\bfixed\b|\/h\b|\/hr\b|per hour|hourly/i.test(String(j.comp || ''))
  || /\[for hire\]|\[hiring\].*\b(task|gig)\b/i.test(String(j.title || ''));
const sections = [
  { name: '🎯 Apply now',    pick: (j) => !isGig(j) && Number(j.score) >= 80 },
  { name: '👀 Worth a look', pick: (j) => !isGig(j) && Number(j.score) < 80 },
  { name: '💼 Gigs & side income', pick: isGig },
];

const card = (j, n, total, sectionName) => {
  const lines = [];
  lines.push(sectionName + ' · ' + n + '/' + total);
  lines.push('⭐ ' + esc(j.score) + ' · ' + esc(j.category || 'other'));
  const titleBits = [j.title, j.company].filter(Boolean).map(esc).join(' — ');
  if (titleBits) lines.push('<b><a href="' + esc(j.url) + '">' + titleBits + '</a></b>');
  if (j.one_liner) lines.push(esc(j.one_liner));
  const posted = postedInfo(j.posted_at);
  if (posted) lines.push('🕒 posted ' + esc(posted.label) + (posted.days >= 30 ? ' — stale' : ''));
  if (j.comp) lines.push('💰 ' + esc(j.comp));
  if (Array.isArray(j.red_flags) && j.red_flags.length > 0) lines.push('⚠️ ' + esc(j.red_flags.join(', ')));
  lines.push('🔗 ' + esc(j.url));
  lines.push('(' + esc(j.source || 'unknown') + ')');
  return lines.join('\n');
};

const date = DateTime.now().setZone(TZ).toISODate();
const counts = sections.map(s => ({ name: s.name, rows: items.filter(s.pick) })).filter(s => s.rows.length > 0);
const header = '🤖 Job Digest — ' + date + ' · ' + items.length + ' shown\n'
  + counts.map(s => s.name + ' ' + s.rows.length).join(' · ');

const out = [{ json: { text: header, archive_id: '' } }];
let n = 0;
for (const s of counts) {
  for (const j of s.rows) {
    n++;
    const id = (j.archive_id === undefined || j.archive_id === null) ? '' : String(j.archive_id);
    out.push({ json: { text: card(j, n, items.length, s.name), archive_id: id, section: s.name } });
  }
}
console.log('Digest: header + ' + (out.length - 1) + ' job cards, ' + out.filter(o => o.json.archive_id !== '').length + ' with buttons');
return out;

const stripHtml = (s) => String(s ?? '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const jobs = Array.isArray(j.jobs) ? j.jobs : [];
  for (const job of jobs) {
    if (!job || !job.title || !job.url) continue;
    const url = String(job.url).trim();
    if (seen.has(url)) continue; // the ai + automation searches overlap
    seen.add(url);
    out.push({ json: {
      title: String(job.title).trim(),
      company: String(job.company_name || '').trim(),
      description: stripHtml(job.description).slice(0, 1500),
      url,
      source: 'remotive',
      posted_at: String(job.publication_date || '')
    } });
  }
}
console.log('Remotive normalized: ' + out.length + ' jobs');
return out;

const stripHtml = (s) => String(s ?? '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const link = j.link || j.guid;
  if (!j.title || !link) continue;
  const rawTitle = String(j.title).trim();
  // WWR feed titles look like 'Company: Job Title'
  let company = '';
  let title = rawTitle;
  const ci = rawTitle.indexOf(':');
  if (ci > 0) { company = rawTitle.slice(0, ci).trim(); title = rawTitle.slice(ci + 1).trim(); }
  out.push({ json: {
    title,
    company,
    description: stripHtml(j.content || j.contentSnippet || '').slice(0, 1500),
    url: String(link).trim(),
    source: 'weworkremotely',
    posted_at: String(j.isoDate || j.pubDate || '')
  } });
}
console.log('WWR normalized: ' + out.length + ' jobs');
return out;

const decodeEntities = (s) => String(s ?? '')
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(parseInt(d, 10)))
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'");

const stripHtml = (s) => decodeEntities(String(s ?? '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/\s+/g, ' ').trim();

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const kids = Array.isArray(j.children) ? j.children : [];
  for (const c of kids) {
    if (!c || !c.id || typeof c.text !== 'string') continue;
    if (!c.text.includes('REMOTE')) continue; // HN convention: uppercase REMOTE in the header line
    const firstLine = stripHtml(c.text.split(/<p>/i)[0]);
    if (!firstLine) continue;

    // HN convention is "Company | Role | Location | Type". When the first line has no pipes
    // it is prose, so cap it hard and do NOT reuse it as the company name.
    const hasPipes = firstLine.includes('|');
    const title = hasPipes ? firstLine.slice(0, 120) : firstLine.slice(0, 80).replace(/\s+\S*$/, '') + '…';
    const company = hasPipes ? firstLine.split('|')[0].trim() : '';

    out.push({ json: {
      title,
      company,
      description: stripHtml(c.text).slice(0, 1500),
      url: 'https://news.ycombinator.com/item?id=' + c.id,
      source: 'hn_whoishiring',
      posted_at: String(c.created_at || '')
    } });
  }
}
console.log('HN normalized: ' + out.length + ' comments');
return out;

const topics = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const list = j.topic_list && Array.isArray(j.topic_list.topics) ? j.topic_list.topics : [];
  for (const t of list) {
    if (!t || t.pinned) continue; // skip pinned board-rules topics
    if (!t.id || !t.slug) continue;
    topics.push({ id: t.id, slug: t.slug, created_at: t.created_at || '' });
  }
}
topics.sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
// cap at 15 newest topics to stay polite to the Discourse API
const out = topics.slice(0, 15).map(t => ({ json: t }));
console.log('n8n board topics to fetch: ' + out.length);
return out;

const stripHtml = (s) => String(s ?? '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.id || !j.slug) continue; // drops error items from failed topic fetches
  const posts = j.post_stream && Array.isArray(j.post_stream.posts) ? j.post_stream.posts : [];
  const first = posts.length > 0 ? posts[0] : null;
  out.push({ json: {
    title: String(j.title || '').trim(),
    company: '',
    description: stripHtml(first ? first.cooked : '').slice(0, 1500),
    url: 'https://community.n8n.io/t/' + j.slug + '/' + j.id,
    source: 'n8n_community',
    posted_at: String(j.created_at || '')
  } });
}
console.log('n8n board normalized: ' + out.length + ' topics');
return out;

// Two independent conditions must BOTH hold before a catch-up digest goes out.
const sd = $getWorkflowStaticData('global');
const now = DateTime.now().setZone('Asia/Bangkok');
const today = now.toISODate();
const hour = now.hour + now.minute / 60;

// (1) TIME WINDOW. The cron says 10:00-23:59, but that is not enough on its own: when the
// laptop wakes from sleep, node-cron replays the missed occurrence IMMEDIATELY, ignoring the
// window. That is exactly how digests went out at 00:38 (exec #345) and 03:02 (exec #324) —
// the local date had rolled over, lastSentDate was still yesterday, so the guard passed and
// fired a full run in the middle of the night. Re-checking the clock here is what actually
// prevents it.
const OPEN = 9.75;   // 09:45 - comfortably after the 09:30 main run has finished
const CLOSE = 23.99;
if (hour < OPEN || hour >= CLOSE) {
  console.log('Catch-up suppressed: ' + now.toFormat('HH:mm') + ' is outside the 09:45-23:59 window (likely a missed tick replayed on wake)');
  return [];
}

// (2) NOT ALREADY SENT. Mark Sent records the date after a successful Telegram delivery.
if (sd.lastSentDate === today) {
  console.log('Digest already sent today (' + today + ') - catch-up not needed');
  return [];
}

console.log('No digest sent yet today (' + today + ') at ' + now.toFormat('HH:mm') + ' - running catch-up');
return [{ json: { catchup: true } }];

// Record that today's digest was delivered, so the hourly Catch-up Guard stops.
// Static data persists only for production (schedule/webhook) executions.
const sd = $getWorkflowStaticData('global');
sd.lastSentDate = DateTime.now().setZone('Asia/Bangkok').toISODate();
console.log('Digest marked sent for ' + sd.lastSentDate);
return $input.all();

const stripHtml = (s) => String(s ?? '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.url || !j.title) continue;
  out.push({ json: {
    title: String(j.title).trim(),
    company: String(j.company_name || '').trim(),
    description: stripHtml(j.description).slice(0, 1500),
    url: String(j.url).trim(),
    source: 'workingnomads',
    posted_at: String(j.pub_date || '')
  } });
}
console.log('Working Nomads normalized: ' + out.length);
return out;

const stripHtml = (s) => String(s ?? '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const out = [];
for (const item of $input.all()) {
  const jobs = (item.json && Array.isArray(item.json.jobs)) ? item.json.jobs : [];
  for (const j of jobs) {
    if (!j || !j.url || !j.jobTitle) continue;
    const type = Array.isArray(j.jobType) ? j.jobType.join('/') : String(j.jobType || '');
    const extra = [j.jobGeo ? 'Location: ' + j.jobGeo : '', type ? 'Type: ' + type : '', j.jobLevel ? 'Level: ' + j.jobLevel : ''].filter(Boolean).join(' | ');
    const desc = stripHtml(String(j.jobDescription || j.jobExcerpt || ''));
    out.push({ json: {
      title: String(j.jobTitle).trim(),
      company: String(j.companyName || '').trim(),
      description: ((extra ? extra + ' | ' : '') + desc).slice(0, 1500),
      url: String(j.url).trim(),
      source: 'jobicy',
      posted_at: String(j.pubDate || '')
    } });
  }
}
console.log('Jobicy normalized: ' + out.length);
return out;

const stripHtml = (s) => String(s ?? '').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/g, "'").replace(/&#\d+;/g, ' ').replace(/\s+/g, ' ').trim();
const out = [];
for (const item of $input.all()) {
  const list = (item.json && Array.isArray(item.json.data)) ? item.json.data : [];
  for (const j of list) {
    if (!j || !j.url || !j.title) continue;
    if (j.remote !== true) continue; // mixed board: keep only remote-flagged postings
    const types = Array.isArray(j.job_types) ? j.job_types.join('/') : '';
    const extra = [j.location ? 'Location: ' + j.location : '', types ? 'Type: ' + types : ''].filter(Boolean).join(' | ');
    const desc = stripHtml(String(j.description || ''));
    out.push({ json: {
      title: String(j.title).trim(),
      company: String(j.company_name || '').trim(),
      description: ((extra ? extra + ' | ' : '') + desc).slice(0, 1500),
      url: String(j.url).trim(),
      source: 'arbeitnow',
      posted_at: j.created_at ? new Date(j.created_at * 1000).toISOString() : ''
    } });
  }
}
console.log('Arbeitnow normalized: ' + out.length);
return out;

// Score Gate (2026-09-14): threshold 40 -> 60 after the gpt-oss-120b swap.
// Post-swap histogram (880 archived jobs) shows 55/58/62/66/72/78 are now common, so the
// "nothing between 41 and 59" property that justified 40 no longer holds. 36 of 136 delivered
// jobs sat in the 40-59 band and none were worth applying to.
//
// Region: reverses the 07-18 decision. 26 us_only + 6 eu_only reached the digest (24% of all
// deliveries); a US-only employer will not contract an Israel-based dev, so there is nothing
// for the human to judge. tz_overlap_required and region_other stay (EMEA/APAC overlap is
// realistic from Israel/Thailand) and remain visible as red flags.
const THRESHOLD = 60;
// Decision 2026-09-14: worldwide-remote only. us_only, eu_only AND region_other (Spain-based,
// LATAM, "EU/UK based", etc.) are all dropped. tz_overlap_required stays — that IS worldwide
// hiring, just with hours to keep, and EMEA/APAC overlap works from Israel/Thailand.
const HARD_DROP_REGION = new Set(['us_only', 'eu_only', 'region_other']);
const ONSITE_RX = /\b(on-?site|hybrid|in-?office|relocat)/i;

const all = $input.all();
let dropped = { region: 0, other: 0, senior: 0, onsite: 0, score: 0 };
const kept = all.filter(i => {
  const j = i.json || {};
  if (j._empty || !j.url) return false;
  if (j.seniority_fit === 'senior_only') { dropped.senior++; return false; }
  if (HARD_DROP_REGION.has(j.region_lock)) { dropped.region++; return false; }
  if (j.category === 'other') { dropped.other++; return false; }
  const flags = Array.isArray(j.red_flags) ? j.red_flags.join(' ') : String(j.red_flags || '');
  if (ONSITE_RX.test(flags)) { dropped.onsite++; return false; }
  if (Number(j.score) < THRESHOLD) { dropped.score++; return false; }
  return true;
});
console.log('Score gate kept ' + kept.length + ' of ' + all.length + ' ' + JSON.stringify(dropped));
if (kept.length === 0) return [{ json: { _empty: true, score: -1 } }];
return kept;

const now = DateTime.now().setZone('Asia/Bangkok').toISO();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j._empty || !j.url) continue;
  out.push({ json: {
    url: String(j.url), title: String(j.title || ''), company: String(j.company || ''),
    source: String(j.source || ''), score: Number(j.score) || 0, category: String(j.category || ''),
    region_lock: String(j.region_lock || ''), seniority_fit: String(j.seniority_fit || ''),
    comp: String(j.comp || ''), one_liner: String(j.one_liner || ''),
    red_flags: Array.isArray(j.red_flags) ? j.red_flags.join(', ') : String(j.red_flags || ''),
    posted_at: String(j.posted_at || ''), first_seen: now, delivered: false
  } });
}
console.log('Archiving ' + out.length + ' scored jobs');
// Zero-job days: emit a sentinel rather than nothing. A node that outputs 0 items
// stops the chain dead, and since the archive write is now IN the digest path that
// would mean no digest at all. 'Has Rows to Archive' routes this sentinel around
// the data-table write so it never becomes a junk row.
if (out.length === 0) return [{ json: { _empty: true } }];
return out;

// CV_READY: set to true once the CV path is configured in the 'Read CV' node.
const CV_READY = false;
if (!CV_READY) { console.log('Apply-assist disabled until CV is configured'); return []; }
const items = $input.all().filter(i => {
  const j = i.json || {};
  return j.url && !j._empty && Number(j.score) >= 80;
});
const top = items.slice(0, 3); // max 3 pitch packages per day
console.log('Apply-assist: preparing ' + top.length + ' pitch packages');
return top;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const jobs = $('Apply Prep').all();
const resp = $input.all();
const out = [];
for (let i = 0; i < resp.length; i++) {
  const j = resp[i].json || {};
  const job = (jobs[i] && jobs[i].json) || {};
  const content = j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content;
  if (!content) { console.log('Pitch draft missing for item ' + i); continue; }
  const pitch = String(content).trim().slice(0, 700);
  const caption = ('📨 <b>Ready to forward</b> — ' + esc(job.title || '') + (job.company ? ' @ ' + esc(job.company) : '') + '\n\n' + esc(pitch) + '\n\n🔗 ' + esc(job.url || '')).slice(0, 1000);
  out.push({ json: { caption, url: job.url || '' } });
}
return out;

// If NOT ONE source produced a real job, the network is almost certainly down
// (laptop just woke, Wi-Fi not connected yet). Fail loudly instead of delivering
// a bogus 'nothing new' digest and marking the day as sent — the hourly catch-up
// will retry once the network is back. Also strips fetch-error items so they
// never pollute the URL dedup history.
const items = $input.all();
const real = items.filter(i => i.json && i.json.url && i.json.title);
if (real.length === 0) {
  throw new Error('All job sources returned nothing - likely no network yet. Aborting so the hourly catch-up retries.');
}
console.log('Source health: ' + real.length + ' real items of ' + items.length);
return real;

// SEQUENCING NODE - do not remove.
// It exists so the archive write (Prep Archive -> Archive Jobs) completes BEFORE the
// digest/apply chain runs. Reordering Parse + Filter's output connections does NOT
// control n8n v1 branch execution order (proven 2026-07-25: archive rows were written
// 3s AFTER the Telegram send, so Mark Delivered always updated rows that did not exist
// yet). Chaining is the only reliable ordering primitive.
// Its own input is the data-table rows, which it ignores; it hands the scored jobs
// straight back to Score Gate.
//
// 2026-09-14: also stamps each job with its archive row id. The digest's inline buttons
// carry that id (callback_data is capped at 64 bytes, urls do not fit) and the Feedback
// workflow looks the job up by it. Archive Jobs does not run on the FALSE branch of
// Has Rows to Archive, so the lookup is guarded; a job without an id just gets no buttons.
const scored = $('Parse + Filter').all();
const idByUrl = {};
try {
  for (const r of $('Archive Jobs').all()) {
    const j = r.json || {};
    if (j.url && j.id !== undefined) idByUrl[j.url] = j.id;
  }
} catch (e) {
  console.log('Archive Jobs output unavailable (' + e.message + ') - no archive_id join');
}
let joined = 0;
const out = scored.map(it => {
  const j = it.json || {};
  const id = idByUrl[j.url];
  if (id !== undefined) joined++;
  return { json: { ...j, archive_id: id !== undefined ? id : '' } };
});
console.log('Resuming digest with ' + out.length + ' scored jobs (archive already written); archive_id joined for ' + joined);
if (out.length === 0) return [{ json: { _empty: true, score: -1 } }];
return out;

// Fires only when today's digest never went out. Mark Sent writes lastSentDate.
const sd = $getWorkflowStaticData('global');
const today = DateTime.now().setZone('Asia/Bangkok').toISODate();
if (sd.lastSentDate === today) {
  console.log('Watchdog: digest already sent for ' + today + ' - staying quiet');
  return [];
}
console.log('Watchdog: NO digest for ' + today + ' (last sent: ' + (sd.lastSentDate || 'never') + ')');
return [{ json: { today, lastSent: sd.lastSentDate || 'never' } }];
